() => {
  const items = [];
  const panel = document.querySelector('.tabpanel');
  if (panel) {
    for (let i = 0; i < panel.children.length; i++) {
      const el = panel.children[i];
      const text = el.innerText.trim();
      if (text && text.length > 5 && text.length < 500) {
        items.push(text);
      }
    }
  }
  return items;
}

() => {
  const panel = document.querySelector('.tabpanel');
  if (panel) {
    const items = [];
    for (let i = 0; i < panel.children.length; i++) {
      const el = panel.children[i];
      // video items typically have text with non-empty content
      const text = el.innerText.trim();
      if (text && text.length > 3 && text.length < 400) {
        items.push(text);
      }
    }
    return items;
  } else {
    return ["Could not find tabpanel"];
  }
}

() => {
  const tabs = document.querySelectorAll('[data-testid="tablist"]');
  const tabsList = [];
  for (const tab of tabs) {
    const label = tab.querySelector('[data-testid="tab"]');
    if (label) {
      tabsList.push({ label: label.innerText.trim(), ...tab });
    }
  }
  return tabsList;
}

() => {
  // Find all tabpanels and their labels
  const panels = document.querySelectorAll('[data-testid="tabpanel"]');
  for (const panel of panels) {
    const label = panel.querySelector('[data-testid="tab"]');
    if (label) {
      const text = label.innerText.trim();
      console.log(text);
    }
  }
}

() => {
  // Search for all elements containing 三农
  const results = [];
  const all = document.querySelectorAll('*');
  for (const el of all) {
    const text = el.innerText.trim();
    if (text && text.includes('三农')) {
      results.push({ el: el, text, uid: el.id });
    }
  }
  return results.slice(0, 20);
}

() => {
  // Find all elements with text containing 三农
  const results = [];
  const all = document.querySelectorAll('*');
  for (const el of all) {
    try {
      if (el.innerText && el.innerText.includes('三农')) {
        results.push({ el: el, text: el.innerText.trim(), uid: el.id });
      }
    } catch(e) {}
  }
  return results;
}

() => {
  // Try to find all tab elements
  const tabs = document.querySelectorAll('[role="tab"]');
  for (let i = 0; i < tabs.length; i++) {
    const label = tabs[i];
    console.log('Tab:', label.innerText?.trim());
  }
}

() => {
  const elements = document.querySelectorAll('*');
  let count = 0;
  for (const el of elements) {
    try {
      const text = el.innerText?.trim();
      if (text && text.length > 0 && text !== '') {
        count++;
        if (count <= 30) {
          console.log(el.id || 'NO-ID', ':', text.substring(0, 100));
        }
      }
    } catch(e) {}
  }
  console.log('Total non-empty:', count);
}

() => {
  // Find the三农 tab panel
  const tab = document.getElementById('1_102');
  if (tab) {
    // Try to get the next sibling or parent to find the panel
    const panel = tab?.parentElement?.parentElement;
    if (panel) {
      const texts = [];
      const items = panel?.querySelectorAll('div');
      for (const item of items) {
        const text = item.innerText?.trim();
        if (text && text.length > 10) {
          texts.push(text);
        }
      }
      return texts.slice(0, 15);
    }
  }
  // Alternative: try to find tabpanel with 三农
  const panels = document.querySelectorAll('[data-testid="tabpanel"]');
  for (const p of panels) {
    const label = p.querySelector('[data-testid="tab"]');
    if (label?.innerText === '三农') {
      const texts = [];
      const items = p?.querySelectorAll('div');
      for (const item of items) {
        const text = item.innerText?.trim();
        if (text && text.length > 10) {
          texts.push(text);
        }
      }
      return texts;
    }
  }
  return [];
}

() => {
  const tabEls = document.querySelectorAll('[data-testid="tab"]');
  console.log(tabEls.length);
  tabEls.forEach(el => {
    const text = el.innerText?.trim();
    if (text === '三农') {
      console.log('Found三农 tab:', el.id, el.tagName);
      // Try to find the panel
      const panel = el?.parentElement?.parentElement;
      if (panel) {
        const texts = Array.from(panel?.querySelectorAll('*')).map(e => e.innerText?.trim());
        console.log('Panel texts:', texts.slice(0, 5));
      }
    }
  });
}

() => {
  const tab = document.querySelector('[data-testid="tab"]');
  const panel = tab?.parentElement?.parentElement;
  if (panel) {
    // Find all video entries in the panel
    const items = Array.from(panel.querySelectorAll('div'));
    const videos = items.filter(el => {
      const text = el.innerText?.trim();
      return text && text.length > 10 && !text.includes('contentinfo');
    });
    return videos.slice(0, 10);
  }
  return [];
}

() => {
  const panels = document.querySelectorAll('[data-testid="tabpanel"]');
  for (const panel of panels) {
    const label = panel.querySelector('[data-testid="tab"]');
    if (label?.innerText === '三农') {
      const texts = Array.from(panel.querySelectorAll('div')).map(el => el.innerText?.trim());
      return texts.filter(t => t && t.length > 10);
    }
  }
  return ["No three panel found"];
}

() => {
  const tab = document.querySelector('[data-testid="tab"]');
  if (!tab) return "No tab found";
  const children = Array.from(tab.children);
  for (const child of children) {
    const text = child.innerText?.trim();
    if (text === '三农') {
      console.log('Found三农 tab:', tab.id, child.id);
      return tab.id;
    }
  }
  return null;
}

() => {
  const panel = document.querySelector('[data-testid="tabpanel"]');
  if (!panel) return [];
  const items = panel.querySelectorAll('div');
  const videos = [];
  for (const item of items) {
    const title = item.querySelector('.title-text') || item.querySelector('strong') || item.innerText;
    if (item.innerText && item.innerText.includes('@') && item.innerText.trim().length > 10) {
      videos.push(item.innerText.trim());
    }
  }
  return videos;
}

() => {
  const panel = document.querySelector('[data-testid="tabpanel"]');
  if (!panel) return [];
  const items = Array.from(panel.querySelectorAll('div'));
  const videos = items.map(el => el.innerText.trim());
  return videos.slice(0, 10);
}
